def run(env):
    """
    Improved sampling policy using:
    1. Multiple prompt variants (not just variant 0)
    2. Verifier score weighting when aggregating answers
    3. Adaptive sampling based on confidence
    """
    out = {}
    budget = env.budget
    n_questions = len(env.questions)

    # Phase 1: Initial sampling from all variants
    answers_by_qid = {}
    for q in env.questions:
        answers_by_qid[q["id"]] = {}

    # Sample each variant once for each question (5 samples/question * 400 = 2000 budget)
    samples_used = 0
    for q in env.questions:
        qid = q["id"]
        for variant in range(env.n_variants):
            if samples_used >= budget:
                break
            answer, score = env.sample(qid, variant)
            if answer not in answers_by_qid[qid]:
                answers_by_qid[qid][answer] = {"count": 0, "score_sum": 0, "scores": []}
            answers_by_qid[qid][answer]["count"] += 1
            answers_by_qid[qid][answer]["score_sum"] += score
            answers_by_qid[qid][answer]["scores"].append(score)
            samples_used += 1
        if samples_used >= budget:
            break

    budget -= samples_used

    # Phase 2: Compute initial answers and confidence scores
    question_confidence = {}
    for q in env.questions:
        qid = q["id"]
        if not answers_by_qid[qid]:
            continue

        # Score each answer: frequency + average verifier score
        best_answer = None
        best_score = float('-inf')
        answer_scores = {}

        for answer, data in answers_by_qid[qid].items():
            count = data["count"]
            avg_score = data["score_sum"] / count
            # Weight: count is important, but also use verifier score
            # Prioritize frequency with some boost from verifier score
            combined_score = count + (avg_score / 3.0)  # verifier score in [-2, 2] range roughly
            answer_scores[answer] = combined_score

            if combined_score > best_score:
                best_score = combined_score
                best_answer = answer

        out[qid] = best_answer

        # Compute confidence as margin between top two answers
        sorted_scores = sorted(answer_scores.values(), reverse=True)
        if len(sorted_scores) >= 2:
            confidence = sorted_scores[0] - sorted_scores[1]
        else:
            confidence = sorted_scores[0]
        question_confidence[qid] = (confidence, best_score)

    # Phase 3: Adaptive re-sampling on low-confidence questions
    if budget > 0:
        # Sort questions by confidence (ascending)
        uncertain_questions = sorted(
            question_confidence.items(),
            key=lambda x: x[1][0]
        )

        # Re-sample the most uncertain questions
        for qid, (confidence, _) in uncertain_questions:
            if budget <= 0:
                break
            if confidence >= 2.0:  # High confidence, skip
                continue

            # Do additional sampling for this question
            num_resamples = min(2, budget)
            for _ in range(num_resamples):
                if budget <= 0:
                    break
                # Sample from best-performing variants so far
                variant = _ % env.n_variants
                answer, score = env.sample(qid, variant)

                if answer not in answers_by_qid[qid]:
                    answers_by_qid[qid][answer] = {"count": 0, "score_sum": 0, "scores": []}
                answers_by_qid[qid][answer]["count"] += 1
                answers_by_qid[qid][answer]["score_sum"] += score
                answers_by_qid[qid][answer]["scores"].append(score)
                budget -= 1

        # Re-compute answers with additional samples
        for q in env.questions:
            qid = q["id"]
